import{_ as r,l as i,o as e,c as n,v as t,p as s,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"厂级数据闭环","description":"","frontmatter":{"title":"厂级数据闭环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fab-data-loop.md","filePath":"litho/fab-data-loop.md","lastUpdated":1789023840000}'),C={name:"litho/fab-data-loop.md"};function A(h,a,c,P,_,D){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="厂级数据闭环" tabindex="-1">厂级数据闭环 <a class="header-anchor" href="#厂级数据闭环" aria-label="Permalink to &quot;厂级数据闭环&quot;">​</a></h1><div class="epigraph"><p>闭环的带宽由数据能不能按时、按键、按版本到达执行器决定；算法再好，也对不上错层、过期、未匹配的数。</p><footer>—— 对照 SEMI 工厂数据与 APC 接口通称；晶圆厂 MES / FDC 与光刻控制的公开架构</footer></div><p><a href="/litho/tool-to-tool-overlay">上一课</a>要求按机台对存指纹。缺口是系统：计量、扫描机、轨道、刻蚀、MES 如何把 ton 级数据收成可用状态。本课钉厂级数据闭环。虚拟计量如何在缺测时充数，留给[下一课](/litho/virtual-metrology）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据闭环：晶圆 id、层、食谱、机台、卡盘、OPC 版本、计量机、时间戳，必须能 join。FDC（故障检测）吃传感器，APC 吃计量，SPC 吃残差，分派吃规格。缺公共键，现场只能做单机小闭环， holistic 停留在幻灯片。延迟：套刻结果晚于下一批已曝光，反馈环开路。</p><p>缺口是<strong>合同与延迟</strong>，不是买一套大数据平台。版本：模型与校正项集必须随数据走，否则用新核解释旧热点。</p><h3 id="fdc-不是-apc" tabindex="-1">FDC 不是 APC <a class="header-anchor" href="#fdc-不是-apc" aria-label="Permalink to &quot;FDC 不是 APC&quot;">​</a></h3><p>振动、激光气体、RF 反射报警的是设备健康，应抑制 APC 或扣留，而不是把振动当 CD 去补剂量。两类系统要握手：FDC 红则 APC 停。</p><p><span class="marginnote">SEMI E133 等描述 APC 系统接口。本课用其精神：数据质量位、限幅、审计，不背诵条款号当内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构：采集 → 上下文对齐 → 质量过滤 → 分发给 APC/SPC/FDC/良率。审计：谁改了剂量偏置。与重工：状态位。与设计：热点坐标回写 LFD 库要走变更控制，不能让产线热点自动改库。安全：配方下载权限。</p><p>延迟预算要按环写：套刻反馈允许晚一批，CD 前馈（胶厚）必须在曝光前到达。对不齐的数据宁可不补，也不要补错层。这是 SEMI APC 接口强调质量位的原因。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭环有效带宽 \\(\\approx\\) 1 /（计量周期 + 对齐 + 队列）。上下文错误等价于增益反号。数据质量位（对焦失败、SEM 充电）必须进滤波器，否则 EWMA 被野点拉跑——匹配与 SPC 课的操作化。</p>',14)),(e(),s(E,null,{default:o(()=>[p(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%20%E8%BD%A8%E9%81%93%20%E5%88%BB%E8%9A%80%20%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20CTX%5B%22%E6%99%B6%E5%9C%86-%E5%B1%82-%E7%89%88%E6%9C%AC%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CTX%20--%3E%20Q%5B%22%E8%B4%A8%E9%87%8F%E4%BD%8D%E8%BF%87%E6%BB%A4%22%5D%0A%20%20Q%20--%3E%20APC%5B%22APC%20%2F%20SPC%20%2F%20FDC%22%5D%0A%20%20FDC%5B%22%E8%AE%BE%E5%A4%87%E5%81%A5%E5%BA%B7%22%5D%20--%3E%20GATE%5B%22%E5%85%81%E8%AE%B8%E8%A1%A5%E5%81%BF%3F%22%5D%0A%20%20GATE%20--%3E%20APC%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>对齐失败等价于增益反号。FDC 红应关掉 APC，避免把振动当 CD 去补剂量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写具体商业 MES 商标当物理定律。不进入大模型训练栈。网络安全只点名权限。</p><p>后课默认：闭环有上下文键、质量位和 FDC 门。下一课在计量稀疏处用虚拟计量，仍受同一质量合同约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厂级闭环靠 join 键、延迟和质量位，而不是靠算法名称。</li><li>FDC 健康门应能关掉 APC。</li><li>模型版本随数据走。</li><li>出处：SEMI APC/工厂数据接口通称；FDC–APC 分工的产线架构。</li></ul>',6))])}const m=r(C,[["render",A]]);export{f as __pageData,m as default};
